def control(obs):
    import math
    status = obs.get('status', '')
    hitch = obs.get('hitch_deg', 0.0)
    # Determine where to look: sweep left/right when target not in sight
    target = obs.get('target', {})
    if not target.get('in_sight', False):
        # Oscillate gaze between -90° and +90° over a 6‑second period
        t = obs.get('t', 0.0)
        look = 90 * math.sin(2 * math.pi * t / 6.0)
    else:
        look = obs.get('head', {}).get('gaze_deg', 0.0)
    # Steering: proportional to hitch angle (steer opposite to trailer swing)
    steer = max(min(-hitch * 0.7, 42), -42)  # clamp to max steering
    # Decide speed based on status and hitch angle
    if status in ('PINNED', 'STOPPED', 'JACKKNIFED'):
        # Pull forward to straighten and recover from contact
        speed = 0.8  # forward m/s
    else:
        # While reversing, keep trailer straight; if hitch too large, pull forward to correct
        if abs(hitch) > 8:
            speed = 0.8  # forward to straighten
        else:
            speed = -0.9  # reverse
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look}

